/**
 * Platform-specific installation information for the Antigravity companion CLI.
 */
export interface AntigravityInstallInfo {
  /** Human-readable name of the detected platform. */
  platformName: string;
  /** The shell command used to install the Antigravity CLI on this platform. */
  installCmd: string;
}

/**
 * Detects the current operating system (and shell, on Windows) and returns the
 * appropriate installation instructions for the Antigravity companion CLI.
 *
 * @returns The install info for the current platform, or `null` when the
 *   platform is not supported.
 */
export function getAntigravityInstallInfo(): AntigravityInstallInfo | null {
  switch (process.platform) {
    case 'darwin':
      return {
        platformName: 'macOS',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.sh | bash',
      };
    case 'linux':
      return {
        platformName: 'Linux',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.sh | bash',
      };
    case 'win32':
      if (process.env['PSModulePath']) {
        return {
          platformName: 'Windows (PowerShell)',
          installCmd: 'irm https://antigravity.google/cli/install.ps1 | iex',
        };
      }
      return {
        platformName: 'Windows (Command Prompt)',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.cmd -o install.cmd && install.cmd && del install.cmd',
      };
    default:
      return null;
  }
}
