import type {
  CountTokensParameters,
  CountTokensResponse,
  EmbedContentParameters,
  EmbedContentResponse,
  GenerateContentParameters,
  GenerateContentResponse,
} from '@google/genai';
import type { UserTierId, GeminiUserTier } from '../code_assist/types.js';
import type { LlmRole } from '../telemetry/llmRole.js';
import type { ContentGenerator } from './contentGenerator.js';

const MODELS_PREFIX = 'models/';

/**
 * A {@link ContentGenerator} decorator that rewrites requested model names
 * before delegating to a wrapped generator.
 *
 * This is used to translate user-facing model names (e.g. those exposed to
 * Google account authentication) into the concrete model names understood by
 * the backend. The optional `models/` prefix used by some APIs is preserved:
 * the prefix is stripped before the lookup and restored afterwards when it was
 * present on the incoming request.
 */
export class ModelMappingContentGenerator implements ContentGenerator {
  constructor(
    private readonly wrapped: ContentGenerator,
    private readonly mappings: Record<string, string>,
  ) {}

  /** Returns the wrapped {@link ContentGenerator}. */
  getWrapped(): ContentGenerator {
    return this.wrapped;
  }

  get userTier(): UserTierId | undefined {
    return this.wrapped.userTier;
  }

  get userTierName(): string | undefined {
    return this.wrapped.userTierName;
  }

  get paidTier(): GeminiUserTier | undefined {
    return this.wrapped.paidTier;
  }

  /**
   * Maps a model name using the provided dictionary, preserving the optional
   * `models/` prefix.
   */
  private mapModel(model: string): string {
    const hasPrefix = model.startsWith(MODELS_PREFIX);
    const bareModel = hasPrefix ? model.slice(MODELS_PREFIX.length) : model;
    const mapped = this.mappings[bareModel] ?? bareModel;
    return hasPrefix ? `${MODELS_PREFIX}${mapped}` : mapped;
  }

  private mapRequest(
    request: GenerateContentParameters,
  ): GenerateContentParameters {
    return { ...request, model: this.mapModel(request.model) };
  }

  generateContent(
    request: GenerateContentParameters,
    userPromptId: string,
    role: LlmRole,
  ): Promise<GenerateContentResponse> {
    return this.wrapped.generateContent(
      this.mapRequest(request),
      userPromptId,
      role,
    );
  }

  generateContentStream(
    request: GenerateContentParameters,
    userPromptId: string,
    role: LlmRole,
  ): Promise<AsyncGenerator<GenerateContentResponse>> {
    return this.wrapped.generateContentStream(
      this.mapRequest(request),
      userPromptId,
      role,
    );
  }

  countTokens(request: CountTokensParameters): Promise<CountTokensResponse> {
    return this.wrapped.countTokens(request);
  }

  embedContent(
    request: EmbedContentParameters,
  ): Promise<EmbedContentResponse> {
    return this.wrapped.embedContent(request);
  }
}
